INSERT INTO `applications` (`id`, `job_id`, `job_title`, `department`, `student_id`, `student_name`, `student_number`, `student_email`, `course`, `year_level`, `sex`, `age`, `phone`, `cover_letter`, `availability`, `resume_file`, `study_load_file`, `status`, `status_label`, `status_badge`, `interview_date`, `interview_time`, `interview_venue`, `supervisor_notes`, `applied_at`, `updated_at`) VALUES (3, 3, 'Digital Cataloging & Library Aid', 'KLD University Library', 2, 'Maria Santos', '2024-00456', 'maria.santos@kld.edu.ph', 'BS Computer Science (BSCS)', '3rd Year', 'Female', 21, '+63 928 234 5678', 'I am applying for the Library Aid role. I spend a lot of time in the KLD library, have high attention to detail, and can commit to morning shifts.', '[\"Monday (8:00 AM - 12:00 PM)\",\"Wednesday (8:00 AM - 12:00 PM)\"]', 'Maria_Santos_Resume.pdf', 'Maria_Santos_StudyLoad.pdf', 'accepted', 'Accepted / Hired', 'success', '2026-08-23', '10:00 AM', 'KLD Main Library 2nd Floor Office', 'Excellent communication skills and schedule fit. Officially approved for 1st Semester duty.', '2026-08-20 11:00:00', '2026-08-24 16:20:00') ON DUPLICATE KEY UPDATE `status`=VALUES(`status`);
